import java.util.*;

public class Main {
    int[] exclusiveTime(int n, List<String> logs) {
        int[] result = new int[n];
        Deque<int[]> running = new ArrayDeque<>();                                  // [function_id, start_timestamp] for every currently-active call
        for (String log : logs) {
            String[] parts = log.split(":");
            int fid = Integer.parseInt(parts[0]);
            int ts = Integer.parseInt(parts[2]);
            if (parts[1].equals("start")) {
                running.push(new int[]{fid, ts});
            } else {
                int[] top = running.pop();
                int duration = ts - top[1] + 1;
                result[top[0]] += duration;
                if (!running.isEmpty()) {                                                // this duration was spent NESTED inside the caller: subtract it back out
                    running.peek()[1] += duration;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<String> logs = Arrays.asList("0:start:0", "1:start:2", "1:end:5", "0:end:6");
        System.out.println(Arrays.toString(solution.exclusiveTime(2, logs)));
    }
}

