#include <bits/stdc++.h>
using namespace std;

vector<int> exclusiveTime(int n, vector<string>& logs) {
    vector<int> result(n, 0);
    vector<pair<int,int>> running;                                                    // {function_id, start_timestamp} for every currently-active call
    for (const string& log : logs) {
        int c1 = log.find(':'), c2 = log.find(':', c1 + 1);
        int fid = stoi(log.substr(0, c1));
        string kind = log.substr(c1 + 1, c2 - c1 - 1);
        int ts = stoi(log.substr(c2 + 1));
        if (kind == "start") {
            running.push_back({fid, ts});
        } else {
            auto [startId, startTs] = running.back();
            running.pop_back();
            int duration = ts - startTs + 1;
            result[startId] += duration;
            if (!running.empty()) {                                                     // this duration was spent NESTED inside the caller: subtract it back out
                running.back().second += duration;
            }
        }
    }
    return result;
}

int main() {
    vector<string> logs = {"0:start:0", "1:start:2", "1:end:5", "0:end:6"};
    vector<int> result = exclusiveTime(2, logs);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

