def exclusive_time(n, logs):
    result = [0] * n
    stack = []                                                              # the call stack: IDs of currently-active (nested) function calls
    prev_time = 0                                                           # the timestamp the LAST log event was processed at
    for log in logs:
        id_str, kind, ts_str = log.split(':')
        fid, ts = int(id_str), int(ts_str)
        if kind == 'start':
            if stack:
                result[stack[-1]] += ts - prev_time                        # credit the gap since the last event to whoever was RUNNING
            stack.append(fid)
            prev_time = ts
        else:
            result[stack.pop()] += ts - prev_time + 1                      # credit the gap PLUS this final inclusive tick to the function ending
            prev_time = ts + 1                                            # the NEXT function (if any) starts counting from right after this tick
    return result


if __name__ == "__main__":
    print(exclusive_time(2, ["0:start:0", "0:start:2", "0:end:5", "1:start:6", "1:end:6", "0:end:7"]))

